<?phprequire_once "db.php";$id = $_GET['id'] ?? '';if (!ctype_digit((string)$id) || (int)$id < 1) {    exit("Invalid Teacher ID");}$result = pg_query_params(    $conn,    "SELECT * FROM teachers WHERE teacher_id = $1",    [$id]);$teacher = pg_fetch_assoc($result);if (!$teacher) {    exit("Teacher Not Found");}$message = "";if (isset($_POST['update_teacher'])) {    $name = trim($_POST['teacher_name']);    $email = trim($_POST['email']);    $phone = trim($_POST['phone']);    $department = trim($_POST['department']);    $update = pg_query_params(        $conn,        "UPDATE teachers         SET teacher_name = $1,             email = $2,             phone = $3,             department = $4         WHERE teacher_id = $5",        [$name, $email, $phone, $department, $id]    );    if ($update) {        header("Location: teacher.php");        exit();    } else {        $message = "Update Failed: " . pg_last_error($conn);    }}?><!DOCTYPE html><html><head>    <title>Edit Teacher</title>    <link rel="stylesheet" href="teacher.css"></head><body><div class="teacher-form">    <h2>Edit Teacher</h2>    <p><?php echo htmlspecialchars($message); ?></p>    <form method="POST">        <input type="text" name="teacher_name"        value="<?php echo htmlspecialchars($teacher['teacher_name']); ?>"        required>        <input type="email" name="email"        value="<?php echo htmlspecialchars($teacher['email']); ?>"        required>        <input type="text" name="phone"        value="<?php echo htmlspecialchars($teacher['phone']); ?>"        required>        <input type="text" name="department"        value="<?php echo htmlspecialchars($teacher['department']); ?>"        required>        <button type="submit" name="update_teacher">            Update Teacher        </button>    </form>    <br>    <a href="teacher.php">Back to Teachers</a></div></body></html>